    const name = el(copy, 'span', 'brpg-season-row-name');
    el(name, 'strong', '', s.name);
    if (item === current) el(name, 'small', 'brpg-season-tag', 'Da data');
    el(copy, 'span', 'brpg-season-date', periodLabel(c, e, item, d.year) || days(item.duration));
